SELECT [Станции(Схема)_ГС].NUMB1120, Имена_станций.NAME, [Станции(Схема)_ГС].Year, [avg_gaz_c]*[Kgaz] AS cena_gaza_ind, [avg_ugol]*[Kugol] AS cena_ugol_ind, [Сравнение цены топлива из разных отчётов].cena_e, [Сравнение цены топлива из разных отчётов].avg_gaz_c AS cena_gaza_2021, [Сравнение цены топлива из разных отчётов].avg_ugol AS cena_ugol_2021, [Сравнение цены топлива из разных отчётов].cena_Be
FROM (([Станции(Схема)_ГС] INNER JOIN [Ценовые индексы] ON [Станции(Схема)_ГС].YEAR = [Ценовые индексы].year) INNER JOIN [Сравнение цены топлива из разных отчётов] ON [Станции(Схема)_ГС].NUMB1120 = [Сравнение цены топлива из разных отчётов].NUMB1120) INNER JOIN Имена_станций ON [Станции(Схема)_ГС].NUMB1120 = Имена_станций.NUMB
WHERE ((([Станции(Схема)_ГС].Year)=2023 Or ([Станции(Схема)_ГС].Year)=2042))
ORDER BY [Станции(Схема)_ГС].numb1, [Станции(Схема)_ГС].Year;
